const config = $input.first().json;

if (!config.githubRepo || config.githubRepo === 'owner/repo') {
  throw new Error('Set GITHUB_REPO to owner/repo before running the workflow.');
}

const [owner, repo] = config.githubRepo.split('/');
if (!owner || !repo) {
  throw new Error('GITHUB_REPO must use owner/repo format.');
}

const since = new Date(Date.now() - Number(config.daysBack || 7) * 24 * 60 * 60 * 1000);
const sinceIso = since.toISOString();
const headers = {
  Accept: 'application/vnd.github+json',
  'User-Agent': 'n8n-weekly-dev-summary'
};
if (config.githubToken) headers.Authorization = `Bearer ${config.githubToken}`;

async function github(path) {
  const url = `https://api.github.com/repos/${owner}/${repo}${path}`;
  const response = await fetch(url, { headers });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`GitHub API ${response.status} for ${url}: ${body.slice(0, 300)}`);
  }
  return response.json();
}

const [commits, closedIssues, closedPulls] = await Promise.all([
  github(`/commits?since=${encodeURIComponent(sinceIso)}&per_page=100`),
  github(`/issues?state=closed&since=${encodeURIComponent(sinceIso)}&per_page=100`),
  github(`/pulls?state=closed&sort=updated&direction=desc&per_page=100`)
]);

const mergedPulls = closedPulls
  .filter((pr) => pr.merged_at && new Date(pr.merged_at) >= since)
  .slice(0, 50)
  .map((pr) => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login,
    mergedAt: pr.merged_at,
    url: pr.html_url
  }));

const issues = closedIssues
  .filter((issue) => !issue.pull_request)
  .slice(0, 50)
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    author: issue.user?.login,
    closedAt: issue.closed_at,
    url: issue.html_url
  }));

const commitItems = commits.slice(0, 80).map((commit) => ({
  sha: commit.sha.slice(0, 7),
  message: commit.commit?.message?.split('\n')[0],
  author: commit.author?.login || commit.commit?.author?.name,
  date: commit.commit?.author?.date,
  url: commit.html_url
}));

const languageName = String(config.language || 'EN').toUpperCase() === 'FR' ? 'French' : 'English';
const activity = {
  repo: config.githubRepo,
  period: { since: sinceIso, until: new Date().toISOString() },
  commits: commitItems,
  closedIssues: issues,
  mergedPullRequests: mergedPulls
};

const prompt = `You are writing a weekly development summary for ${config.githubRepo}.

Write in ${languageName}. Make it narrative and useful for engineering stakeholders.

Use this structure:
1. Executive summary: 3-5 bullets.
2. What shipped: group merged pull requests and important commits by theme.
3. Bugs and maintenance: summarize closed issues and maintenance work.
4. Contributors: mention notable contributors from commits and PRs.
5. Risks or follow-ups: infer only from the supplied data; say when data is insufficient.

Rules:
- Do not invent releases, metrics, or roadmap items.
- Link PRs, issues, and commits when URLs are available.
- Keep the summary concise enough for Discord.

GitHub activity JSON:
${JSON.stringify(activity, null, 2)}`;

return [{
  json: {
    ...config,
    since: sinceIso,
    activity,
    prompt
  }
}];

const claude = $input.first().json;
const text = claude.content?.map((part) => part.text || '').join('\n').trim();
if (!text) {
  throw new Error('Claude response did not contain text content.');
}

const previous = $('Fetch GitHub Activity').first().json;
const title = `Weekly dev summary: ${previous.githubRepo}`;
const content = `## ${title}\n\n${text}`;

return [{
  json: {
    discordWebhookUrl: previous.discordWebhookUrl,
    githubRepo: previous.githubRepo,
    since: previous.since,
    summary: text,
    discordPayload: {
      username: 'Weekly Dev Summary',
      content: content.length > 1900 ? content.slice(0, 1890) + '\n…' : content
    }
  }
}];
